insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000500211', '40000000-0000-4000-8000-000000050021', 'A', '$x=1$', 1), ('50000000-0000-4000-8000-000000500212', '40000000-0000-4000-8000-000000050021', 'B', '$x=2$', 2), ('50000000-0000-4000-8000-000000500213', '40000000-0000-4000-8000-000000050021', 'C', '$x=-1$', 3), ('50000000-0000-4000-8000-000000500214', '40000000-0000-4000-8000-000000050021', 'D', '$x=0$', 4)
