insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000050041', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000007', 'multiple_choice', 'hard', 'published', 'Use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-2$, partindo de $x_0=2$. Qual é $x_1$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000500411', '40000000-0000-4000-8000-000000050041', 'A', '$\frac{6}{4}$', 1), ('50000000-0000-4000-8000-000000500412', '40000000-0000-4000-8000-000000050041', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000500413', '40000000-0000-4000-8000-000000050041', 'C', '$1$', 3), ('50000000-0000-4000-8000-000000500414', '40000000-0000-4000-8000-000000050041', 'D', '$\frac{2}{2}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000050041', '50000000-0000-4000-8000-000000500411') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000050041', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000500411', '40000000-0000-4000-8000-000000050041', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 1), ('60000000-0000-4000-8000-000000500412', '40000000-0000-4000-8000-000000050041', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000050041', '$x_1=\frac{6}{4}$.', 'O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000500411', '40000000-0000-4000-8000-000000050041', 'Derive', '$f^{\prime}(x)=2x.$', 1), ('70000000-0000-4000-8000-000000500412', '40000000-0000-4000-8000-000000050041', 'Aplique Newton', '$x_1=2-\frac{4-2}{2\cdot 2}.$', 2), ('70000000-0000-4000-8000-000000500413', '40000000-0000-4000-8000-000000050041', 'Simplifique', '$x_1=\frac{6}{4}.$', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000050042', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000007', 'multiple_choice', 'hard', 'published', 'Use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-6$, partindo de $x_0=3$. Qual é $x_1$?')
